// Some portions generated by Claude
package org.eclipse.rdf4j.sail.memory;

import static org.junit.jupiter.api.Assertions.assertEquals;

import java.io.StringReader;
import java.util.ArrayList;
import java.util.List;
import java.util.stream.Collectors;

import org.eclipse.rdf4j.query.BindingSet;
import org.eclipse.rdf4j.query.TupleQuery;
import org.eclipse.rdf4j.query.TupleQueryResult;
import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.eclipse.rdf4j.repository.sail.SailRepositoryConnection;
import org.eclipse.rdf4j.rio.RDFFormat;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

/**
 * End-to-end guards for {@code FilterOptimizer.FilterRelocator}: a filter may only be pushed into one operand of a
 * Join/LeftJoin when every filter variable is either assured there or cannot be bound by the sibling operand. Pushing
 * on <em>possible</em> names lets a row whose OPTIONAL (or UNDEF VALUES row) left the variable unbound reach the filter
 * before the sibling binds it, so the filter errors and the row is lost.
 */
public class FilterRelocationSoundnessTest {

	private static final String PREFIX = "PREFIX : <http://ex/>\n";

	private SailRepository repository;

	@BeforeEach
	public void setUp() {
		repository = new SailRepository(new MemoryStore());
		repository.init();
	}

	@AfterEach
	public void tearDown() {
		repository.shutDown();
	}

	private void load(String trig) throws Exception {
		try (SailRepositoryConnection conn = repository.getConnection()) {
			conn.add(new StringReader("@prefix : <http://ex/> .\n" + trig), "http://ex/", RDFFormat.TRIG);
		}
	}

	private List<String> rows(String query, String... vars) {
		try (SailRepositoryConnection conn = repository.getConnection()) {
			TupleQuery tupleQuery = conn.prepareTupleQuery(PREFIX + query);
			List<String> result = new ArrayList<>();
			try (TupleQueryResult res = tupleQuery.evaluate()) {
				for (BindingSet bs : res) {
					StringBuilder sb = new StringBuilder();
					for (String var : vars) {
						sb.append(var).append('=').append(bs.getValue(var)).append(' ');
					}
					result.add(sb.toString().trim());
				}
			}
			return result.stream().sorted().collect(Collectors.toList());
		}
	}

	private static StringBuilder filler(String predicate, int count) {
		StringBuilder sb = new StringBuilder();
		for (int i = 0; i < count; i++) {
			sb.append(":f").append(i).append(' ').append(predicate).append(" :fv").append(i).append(" .\n");
		}
		return sb;
	}

	/** Filter variable ?x is only possibly bound by the OPTIONAL but assured by the sibling pattern. */
	@Test
	public void filterIsNotPushedOntoLeftJoinWhenSiblingBindsTheOptionalVariable() throws Exception {
		load(":s1 :p :v . :s1 :r :v .\n" + filler(":r", 200));
		String query = "SELECT ?s ?x ?y WHERE { ?s :p ?y OPTIONAL { ?s :q ?x } ?s :r ?x FILTER(?x = ?y) }";
		assertEquals(List.of("s=http://ex/s1 x=http://ex/v y=http://ex/v"), rows(query, "s", "x", "y"));
	}

	/** Two stacked OPTIONALs bind the same variable: the filter must stay above the outer LeftJoin. */
	@Test
	public void filterIsNotPushedIntoOuterLeftJoinWhenBothOptionalsBindTheVariable() throws Exception {
		load(":s1 :p :o1 . :s1 :r :v .\n" + ":s2 :p :o2 . :s2 :q :v .\n" + ":s3 :p :o3 . :s3 :q :w . :s3 :r :v .\n");
		String query = "SELECT ?s ?x WHERE { ?s :p ?o OPTIONAL { ?s :q ?x } OPTIONAL { ?s :r ?x } FILTER(?x = :v) }";
		// s1: x from second OPTIONAL; s2: x from first OPTIONAL; s3: x = :w from the first OPTIONAL (second is
		// incompatible) -> filtered out
		assertEquals(List.of("s=http://ex/s1 x=http://ex/v", "s=http://ex/s2 x=http://ex/v"), rows(query, "s", "x"));
	}

	/** A VALUES column with UNDEF only possibly binds ?x; the filter belongs on the pattern that assures it. */
	@Test
	public void sameTermFilterIsNotPushedOntoValuesWithUndefColumn() throws Exception {
		load(":s1 :p :v .\n");
		String query = "SELECT ?s ?x WHERE { VALUES ?x { UNDEF :w } ?s :p ?x FILTER(sameTerm(?x, :v)) }";
		assertEquals(List.of("s=http://ex/s1 x=http://ex/v"), rows(query, "s", "x"));
	}

	@Test
	public void sameTermFilterIsNotPushedOntoTwoColumnValuesWithUndef() throws Exception {
		load(":s1 :p :v .\n");
		String query = "SELECT ?s ?x ?y WHERE { VALUES (?x ?y) { (UNDEF :a) (:w :b) } ?s :p ?x FILTER(sameTerm(?x, :v)) }";
		assertEquals(List.of("s=http://ex/s1 x=http://ex/v y=http://ex/a"), rows(query, "s", "x", "y"));
	}

	/** Regression guard: a filter whose variables are assured by one operand still evaluates correctly when pushed. */
	@Test
	public void filterOnAssuredVariableStillFiltersCorrectly() throws Exception {
		load(":s1 :p :v . :s1 :r :a .\n:s2 :p :w . :s2 :r :b .\n");
		String query = "SELECT ?s ?y ?x WHERE { ?s :p ?y . ?s :r ?x FILTER(?y = :v) }";
		assertEquals(List.of("s=http://ex/s1 y=http://ex/v x=http://ex/a"), rows(query, "s", "y", "x"));
	}

	/** Regression guard: the sibling cannot bind ?x, so pushing into the LeftJoin is still allowed and correct. */
	@Test
	public void filterOnOptionalOnlyVariableStillFiltersCorrectly() throws Exception {
		load(":s1 :p :o . :s1 :q :v . :s1 :r :a .\n:s2 :p :o . :s2 :q :w . :s2 :r :b .\n:s3 :p :o . :s3 :r :c .\n");
		String query = "SELECT ?s ?x ?z WHERE { ?s :p ?o OPTIONAL { ?s :q ?x } ?s :r ?z FILTER(?x = :v) }";
		assertEquals(List.of("s=http://ex/s1 x=http://ex/v z=http://ex/a"), rows(query, "s", "x", "z"));
	}
}
